200	/**
201	 * Enable all hooks by clearing the disabled list
202	 */
203	async function enableAllAction(
204	  context: CommandContext,
205	): Promise<void | MessageActionReturn> {
206	  const { config } = context.services;
207	  if (!config) {
208	    return {
209	      type: 'message',
210	      messageType: 'error',
211	      content: 'Config not loaded.',
212	    };
213	  }
214	
215	  const hookSystem = config.getHookSystem();
216	  if (!hookSystem) {
217	    return {
218	      type: 'message',
219	      messageType: 'error',
220	      content: 'Hook system is not enabled.',
221	    };
222	  }
223	
224	  const settings = context.services.settings;
225	  const allHooks = hookSystem.getAllHooks();
226	
227	  if (allHooks.length === 0) {
228	    return {
229	      type: 'message',
230	      messageType: 'info',
231	      content: 'No hooks configured.',
232	    };
233	  }
234	
235	  const disabledHooks = allHooks.filter((hook) => !hook.enabled);
236	  if (disabledHooks.length === 0) {
237	    return {
238	      type: 'message',
239	      messageType: 'info',
240	      content: 'All hooks are already enabled.',
241	    };
242	  }
243	
244	  try {
245	    const scopes = [SettingScope.Workspace, SettingScope.User];
246	    for (const scope of scopes) {
247	      if (isLoadableSettingScope(scope)) {
248	        settings.setValue(scope, 'hooksConfig.disabled', []);
249	      }
250	    }
251	
252	    for (const hook of disabledHooks) {
253	      const hookName = getHookDisplayName(hook);
254	      hookSystem.setHookEnabled(hookName, true);
255	    }
256	
257	    return {
258	      type: 'message',
259	      messageType: 'info',
260	      content: `Enabled ${disabledHooks.length} hook(s) successfully.`,
261	    };
262	  } catch (error) {
263	    return {
264	      type: 'message',
265	      messageType: 'error',
266	      content: `Failed to enable hooks: ${getErrorMessage(error)}`,
267	    };
268	  }
269	}
