import type React from 'react';
import { useMemo, useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { type Key, useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry displayed within the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  enabled: boolean;
  matcher?: string;
  sequential?: boolean;
}

export interface HooksDialogProps {
  hooks: HookEntry[];
  onClose: () => void;
  /**
   * The maximum number of hooks to render at once. When the total number of
   * hooks exceeds this value the list becomes scrollable and scroll indicators
   * are shown.
   */
  maxVisibleHooks?: number;
}

/**
 * Resolve a friendly display name for a hook, falling back to its command when
 * no explicit name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const maxVisible =
    maxVisibleHooks && maxVisibleHooks > 0 ? maxVisibleHooks : hooks.length;
  const canScroll = hooks.length > maxVisible;
  const maxOffset = Math.max(0, hooks.length - maxVisible);

  // Clamp the current offset in case props change underneath us.
  const clampedOffset = Math.min(scrollOffset, maxOffset);

  useKeypress(
    (key: Key) => {
      if (key.name === 'escape') {
        onClose();
        return true;
      }
      if (!canScroll) {
        return false;
      }
      if (key.name === 'up') {
        setScrollOffset((prev) => Math.max(0, prev - 1));
        return true;
      }
      if (key.name === 'down') {
        setScrollOffset((prev) => Math.min(maxOffset, prev + 1));
        return true;
      }
      return false;
    },
    { isActive: true },
  );

  // Only the hooks within the current scroll window are rendered, but they are
  // still grouped by event name for readability.
  const visibleHooks = useMemo(
    () => hooks.slice(clampedOffset, clampedOffset + maxVisible),
    [hooks, clampedOffset, maxVisible],
  );

  const hooksByEvent = useMemo(() => {
    return visibleHooks.reduce(
      (acc, hook) => {
        (acc[hook.eventName] ??= []).push(hook);
        return acc;
      },
      {} as Record<string, HookEntry[]>,
    );
  }, [visibleHooks]);

  const showUpIndicator = canScroll && clampedOffset > 0;
  const showDownIndicator = canScroll && clampedOffset < maxOffset;

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.default}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {hooks.length === 0 ? (
        <Box paddingLeft={2} marginTop={1}>
          <Text color={theme.text.secondary}>No hooks configured.</Text>
        </Box>
      ) : (
        <>
          {showUpIndicator && (
            <Box paddingLeft={2}>
              <Text color={theme.text.secondary}>▲</Text>
            </Box>
          )}
          <Box flexDirection="column" paddingLeft={2} marginTop={1}>
            {Object.entries(hooksByEvent).map(([eventName, eventHooks]) => (
              <Box key={eventName} flexDirection="column" marginBottom={1}>
                <Text color={theme.text.accent} bold>
                  {eventName}:
                </Text>
                <Box flexDirection="column" paddingLeft={2}>
                  {eventHooks.map((hook, index) => {
                    const hookName = getHookDisplayName(hook);
                    const statusColor = hook.enabled
                      ? theme.status.success
                      : theme.text.secondary;
                    const statusText = hook.enabled ? 'enabled' : 'disabled';

                    return (
                      <Box
                        key={`${eventName}-${index}`}
                        flexDirection="column"
                      >
                        <Box>
                          <Text>
                            <Text color={theme.text.accent}>{hookName}</Text>
                            <Text
                              color={statusColor}
                            >{` [${statusText}]`}</Text>
                          </Text>
                        </Box>
                        <Box paddingLeft={2} flexDirection="column">
                          {hook.config.description && (
                            <Text italic>{hook.config.description}</Text>
                          )}
                          <Text dimColor>
                            Source: {hook.source}
                            {hook.config.name &&
                              hook.config.command &&
                              ` | Command: ${hook.config.command}`}
                            {hook.matcher && ` | Matcher: ${hook.matcher}`}
                            {hook.sequential && ` | Sequential`}
                            {hook.config.timeout &&
                              ` | Timeout: ${hook.config.timeout}s`}
                          </Text>
                        </Box>
                      </Box>
                    );
                  })}
                </Box>
              </Box>
            ))}
          </Box>
          {showDownIndicator && (
            <Box paddingLeft={2}>
              <Text color={theme.text.secondary}>▼</Text>
            </Box>
          )}
        </>
      )}

      <Box marginTop={1} flexDirection="column">
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
        <Text color={theme.text.secondary}>
          {canScroll ? 'Use ↑/↓ to scroll. ' : ''}Press Esc to close.
        </Text>
      </Box>
    </Box>
  );
};
